bounded_host_request.command:
set -eu
docker exec -i debug-ai-debug-ai-1 node - <<'NODE'
const fs=require("node:fs"),path=require("node:path"),{decodeEnvelope}=require("/app/orchestrator/durable-primitives.js"),{RuntimeEvidenceStore}=require("/app/server/runtime-evidence.js");
const store=new RuntimeEvidenceStore("/app/runtime");
const ids=["run_mwyug9t6_1bf371e77e","run_mwyw55et_8fc58ab3bb","run_mwyvc8ve_8a1457c11b"];
const root="/app/runtime/durable/durable/run-state-v2";
for(const id of ids){const p=path.join(root,id+".json");const d=fs.existsSync(p)?decodeEnvelope(fs.readFileSync(p),{expectedSchema:"run-state/v2"}):null;
const a=store.list(id,{types:["analysis"],limit:1})[0]?.payload;
console.log(JSON.stringify({id,durable:d?.job_status,analysis_present:!!a,diagnosis_status:a?.diagnosis?.diagnosis_status,review:a?.external_hypothesis_review?.json?.verdict||a?.local_hypothesis_review?.json?.verdict,red:a?.deterministic_verification?.checks?.filter(c=>c.executed&&c.status==="FAIL").length}));}
const active=fs.readdirSync(root).filter(x=>/^run_.*[.]json$/.test(x)).map(f=>decodeEnvelope(fs.readFileSync(path.join(root,f)),{expectedSchema:"run-state/v2"})).filter(x=>!["DONE","BLOCKED","FAILED","CANCELLED","PAUSED"].includes(x.job_status));
console.log("ACTIVE",JSON.stringify(active.map(x=>({run_id:x.run_id,project_id:x.project_id,job_status:x.job_status,project_dir:x.project_dir}))));
NODE
